<?php if(!isAdmin()){flash('error','Acesso restrito.');redirect('index.php?page=dashboard');}$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.action LIKE ? OR a.entity LIKE ? OR a.details LIKE ? ORDER BY a.id DESC LIMIT 200');$st->execute(["%$q%","%$q%","%$q%"]);$rows=$st->fetchAll();$title='Auditoria';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Auditoria</h1><p>Rastreabilidade das principais ações do sistema.</p></div></div><section class="panel"><form class="search"><input name="q" value="<?=e($q)?>" placeholder="Ação, módulo ou detalhe"><button class="btn">Filtrar</button></form><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>Detalhes</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y H:i:s',strtotime($r['created_at']))?></td><td><?=e($r['user_name']?:'Sistema')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity'])?> <?=e($r['entity_id'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
